def singularize(word):
    suffix_rules = [
        ('ies', lambda w: len(w) > 3, lambda w: w[:-3] + 'y'),
        ('ses', lambda w: True, lambda w: w[:-2]),
        ('xes', lambda w: True, lambda w: w[:-2]),
        ('zes', lambda w: True, lambda w: w[:-2]),
        ('ches', lambda w: True, lambda w: w[:-2]),
        ('shes', lambda w: True, lambda w: w[:-2]),
    ]
    for suffix, condition, transform in suffix_rules:
        if word.endswith(suffix) and condition(word):
            return transform(word)
    if word.endswith('s') and not word.endswith('ss'):
        return word[:-1]
    return word

