def subtract_days_from_date(y, m, d, n):
    def is_leap(year):
        return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)
    cum = [0, 31, 59, 90, 120, 151, 181, 212, 243, 273, 304, 334]
    def to_ordinal(year, month, day):
        leap_days = (year - 1) // 4 - (year - 1) // 100 + (year - 1) // 400
        ordinal = (year - 1) * 365 + leap_days + cum[month - 1] + day
        if month > 2 and is_leap(year):
            ordinal += 1
        return ordinal
    def from_ordinal(ordinal):
        year = ordinal * 400 // 146097 + 1
        while to_ordinal(year + 1, 1, 1) <= ordinal:
            year += 1
        while to_ordinal(year, 1, 1) > ordinal:
            year -= 1
        month = 1
        while month < 12 and to_ordinal(year, month + 1, 1) <= ordinal:
            month += 1
        day = ordinal - to_ordinal(year, month, 1) + 1
        return (year, month, day)
    return from_ordinal(to_ordinal(y, m, d) - n)

