def capitalize_after_delimiter(s, delim):
    chars = list(s)
    need_cap = False
    i = 0
    while i < len(chars):
        ch = chars[i]
        if need_cap and ch.isalpha():
            chars[i] = ch.upper()
            need_cap = False
        if ch == delim:
            need_cap = True
        i += 1
    return ''.join(chars)

from itertools import cycle

def alternate_upper_lower(s):
    casers = cycle([str.upper, str.lower])
    result = []
    for ch in s:
        if ch.isalpha():
            caser = next(casers)
            result.append(caser(ch))
        else:
            result.append(ch)
    return "".join(result)

def oxford_join_numbers(numbers):
