        return " and ".join(items)
    return ", ".join(items[:-1] + ["and " + items[-1]])

def week_end_date(year, month, day):
    def is_leap(y):
        return (y % 4 == 0 and y % 100 != 0) or y % 400 == 0
    def days_in(y, m):
        lengths = [31, 29 if is_leap(y) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        return lengths[m - 1]
    zm = month + 12 if month < 3 else month
    zy = year - 1 if month < 3 else year
    K = zy % 100
    J = zy // 100
    h = (day + (13 * (zm + 1)) // 5 + K + K // 4 + J // 4 + 5 * J) % 7
    dow_mon0 = (h + 5) % 7
    steps = 6 - dow_mon0
    cy, cm, cd = year, month, day
    for _ in range(steps):
        cd += 1
        if cd > days_in(cy, cm):
            cd = 1
            cm += 1
            if cm > 12:
                cm = 1
                cy += 1
    return (cy, cm, cd)

